  // AI-generated START - 构建头部
  /// 构建头部：显示年月和关闭按钮
  Widget _buildHeader(BuildContext context, CalendarProvider provider) {
    final month = provider.currentMonth;
    final monthText = '${month.year}年${month.month}月';

    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
