  // AI-generated START - 构建日历网格
  /// 构建日历网格
  Widget _buildCalendarGrid(BuildContext context, CalendarProvider provider) {
    final month = provider.currentMonth;
    final today = DateTime.now();

    // 获取该月第一天是星期几（0=周日，1=周一...）
    final firstDay = DateTime(month.year, month.month, 1);
    final firstDayWeekday = firstDay.weekday % 7; // 转换为0=周日

    // 获取该月有多少天
    final daysInMonth = DateTime(month.year, month.month + 1, 0).day;

    // 计算需要显示的总天数（包括上个月的末尾几天）
    final totalCells = firstDayWeekday + daysInMonth;
    final rows = (totalCells / 7).ceil();

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: List.generate(rows, (rowIndex) {
        return Row(
          mainAxisSize: MainAxisSize.min,
          children: List.generate(7, (colIndex) {
            final cellIndex = rowIndex * 7 + colIndex;
            final dateIndex = cellIndex - firstDayWeekday;

            // 如果是上个月的日期，显示为空
            if (dateIndex < 0 || dateIndex >= daysInMonth) {
              return const Expanded(child: SizedBox());
            }

            final date = DateTime(month.year, month.month, dateIndex + 1);
            final isSelected = provider.selectedDate != null &&
                provider.selectedDate!.year == date.year &&
                provider.selectedDate!.month == date.month &&
                provider.selectedDate!.day == date.day;
            final hasEvent = provider.hasEvent(date);
            final isToday = date.year == today.year && date.month == today.month && date.day == today.day;

            return Expanded(
              child: _buildDateCell(
                context,
                provider,
                date,
                isSelected,
                hasEvent,
                isToday,
              ),
            );
          }),
        );
      }),
    );
  }
  // AI-generated END - 构建日历网格

  // AI-generated START - 构建日期单元格
