  Widget _buildDateCell(
    BuildContext context,
    CalendarProvider provider,
    DateTime date,
    bool isSelected,
    bool hasEvent,
    bool isToday,
  ) {
    return InkWell(
      onTap: () {
        provider.selectDate(date);
        if (onDateSelected != null) {
          onDateSelected!(date);
          Navigator.of(context).pop();
        }
      },
      borderRadius: BorderRadius.circular(8.0),
      child: Container(
        margin: const EdgeInsets.all(8.0),
        height: 40.0,
        decoration: BoxDecoration(
          color: isSelected
              ? const Color(0xFF2196F3) // 选中：蓝色背景
              : hasEvent
                  ? const Color(0xFFE3F2FD) // 有事件：浅蓝色背景
                  : Colors.transparent,
          borderRadius: BorderRadius.circular(8.0),
        ),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              '${date.day}',
              style: TextStyle(
                fontSize: 16.0,
                fontWeight: isSelected ? FontWeight.w600 : FontWeight.w400,
                color: isSelected ? Colors.white : const Color(0xFF212121),
              ),
            ),
            if (hasEvent && !isSelected)
              Container(
                margin: const EdgeInsets.only(top: 2.0),
                width: 4.0,
                height: 4.0,
                decoration: const BoxDecoration(
                  color: Color(0xFF2196F3),
                  shape: BoxShape.circle,
                ),
              ),
          ],
        ),
      ),
    );
  }
  // AI-generated END - 构建日期单元格

  // AI-generated START - 构建回到今天按钮
  /// 构建"回到今天"按钮
  Widget _buildGoToTodayButton(BuildContext context, CalendarProvider provider) {
    return SizedBox(
      width: double.infinity,
      child: ElevatedButton(
        onPressed: () {
          provider.goToToday();
          if (onDateSelected != null && provider.selectedDate != null) {
            onDateSelected!(provider.selectedDate!);
            Navigator.of(context).pop();
          }
        },
        style: ElevatedButton.styleFrom(
          backgroundColor: const Color(0xFF2196F3),
          foregroundColor: Colors.white,
          padding: const EdgeInsets.symmetric(vertical: 14.0),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(8.0),
          ),
          elevation: 0,
        ),
        child: const Text(
          '回到今天',
          style: TextStyle(
            fontSize: 16.0,
            fontWeight: FontWeight.w500,
          ),
        ),
      ),
    );
  }
  // AI-generated END - 构建回到今天按钮
